<script setup>
import AppointmentStatusBadge from './AppointmentStatusBadge.vue';import {appointmentLink,formatDate} from '../../utils/appointmentDates';
defineProps({rows:{type:Array,default:()=>[]},meta:Object});defineEmits(['page']);
