<template><div class="appointment-list-scroll"><table class="appointment-list"><thead><tr><th>Date / Time</th><th>Patient</th><th>Doctor / Type</th><th>Branch</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{formatDate(a.starts_at.slice(0,10))}}<small>{{a.starts_at.slice(11,16)}} – {{a.ends_at.slice(11,16)}}</small></td><td><strong>{{a.patient.full_name}}</strong><small>{{a.patient.patient_number}} · {{a.patient.phone || 'No phone'}}</small></td><td>{{a.doctor.full_name}}<small>{{a.type || 'Appointment'}}</small></td><td>{{a.branch}}</td><td><AppointmentStatusBadge :status="a.status"/></td><td><RouterLink :to="appointmentLink(a)" class="btn-secondary">View</RouterLink></td></tr></tbody></table></div><div class="appointment-list-mobile"><RouterLink v-for="a in rows" :key="a.id" :to="appointmentLink(a)" class="appointment-agenda-card"><div><strong>{{a.patient.full_name}}</strong><AppointmentStatusBadge :status="a.status"/></div><p>{{formatDate(a.starts_at.slice(0,10))}} · {{a.starts_at.slice(11,16)}} – {{a.ends_at.slice(11,16)}}</p><p>{{a.doctor.full_name}} · {{a.type || 'Appointment'}}</p><small>{{a.branch}} · {{a.patient.phone}}</small></RouterLink></div><p v-if="!rows.length" class="empty-state">No appointments match your search.</p><div v-if="meta" class="patient-pagination"><span>{{meta.total}} appointments · Page {{meta.current_page}} of {{meta.last_page}}</span><button class="btn-secondary" :disabled="meta.current_page<=1" @click="$emit('page',meta.current_page-1)">Previous</button><button class="btn-secondary" :disabled="meta.current_page>=meta.last_page" @click="$emit('page',meta.current_page+1)">Next</button></div></template>
